// GOLD CHAIN CATALOGUE ENGINE — CONFIG
// Everything you might want to change lives in this one node. Nothing else in either
// workflow needs editing.
//
// The same config node ships in BOTH workflows ("01 reprice and announce" and
// "02 WhatsApp enquiries"). build.js regenerates both from this one file, and validate.js
// fails if they drift apart, so you never paste it between them by hand.
//
// A blank id or key means that step is SKIPPED, never that the run fails. Both workflows run
// end to end on the built-in demo stock, demo gold rate and demo customers below, which is
// what lets this be shown on a screen-share before a single credential exists.

// ---------------------------------------------------------------- The business
const BUSINESS_NAME   = 'Demo Gold Wholesale';
const OWNER_NAME      = 'the owner';
// The owner's WhatsApp number, international format. Drafts and hand-offs go here.
const OWNER_WHATSAPP  = '';
const CURRENCY        = 'USD';
const CURRENCY_SYMBOL = '$';

// ---------------------------------------------------------------- Pricing
// Wholesale gold is priced off the day's rate. A chain's price is
//   weight (g) x purity x today's 24k rate per gram     <- the metal
// + weight (g) x the style's making charge per gram     <- the work
// then the wholesale margin on top, rounded.
// Purity is the fraction of pure gold for each karat. A row whose karat is not in this table
// is held back rather than priced on a guess.
const PURITY = { 24: 0.999, 22: 0.916, 21: 0.875, 18: 0.750, 14: 0.585 };

// One entry per chain style you carry. `words` are what customers type on WhatsApp to mean
// it. The making charge is per gram, in CURRENCY.
const STYLES = {
  rope:   { label: 'Rope',   making_per_gram: 3.5, words: ['rope', 'twisted'] },
  cuban:  { label: 'Cuban',  making_per_gram: 4.0, words: ['cuban', 'curb', 'miami'] },
  figaro: { label: 'Figaro', making_per_gram: 3.0, words: ['figaro'] },
  box:    { label: 'Box',    making_per_gram: 2.5, words: ['box', 'venetian'] },
  franco: { label: 'Franco', making_per_gram: 4.5, words: ['franco'] },
  ball:   { label: 'Ball',   making_per_gram: 2.0, words: ['ball', 'bead'] }
};

const WHOLESALE_MARGIN_PCT = 2.0;
const ROUND_TO             = 1;      // round every price to this many CURRENCY units

// ---------------------------------------------------------------- The gold rate
// Today's 24k rate per gram, from goldapi.io (free tier is enough for once a day).
// Blank -> the demo rate below is used, and every message says so.
const GOLD_API_KEY  = '';
const GOLD_API_BASE = 'https://www.goldapi.io/api';

// The gate that stops a bad number reaching every customer. Gold rarely moves more than a
// few percent in a day; a bigger move since the last list is far more likely to be a wrong
// currency, a stale cache or a typo than the market. Above this, nothing is published and
// the owner is told why.
const MAX_RATE_MOVE_PCT = 3.0;

// ---------------------------------------------------------------- The stock sheet
// One Google Sheet, two tabs. Blank id -> the demo stock and demo customers below.
//   Stock:     sku | style | purity_k | length_in | weight_g | qty | price | rate | priced_qty | priced_at
//   Customers: name | whatsapp | opted_out
// `price`, `rate`, `priced_qty` and `priced_at` are written by workflow 01: they are what the
// last published list said, which is how the next run knows what is new or sold out.
const SHEET_ID        = '';
const STOCK_TAB       = 'Stock';
const CUSTOMERS_TAB   = 'Customers';
const LOW_STOCK_AT    = 2;           // at or below this many pieces, a chain is "last few"

// ---------------------------------------------------------------- WhatsApp (Twilio)
// Your Twilio WhatsApp sender, international format. Blank -> nothing is sent; every message
// is built in full and shown on a STOP node instead. The Twilio account itself goes in n8n's
// credential store, on the nodes named [cred] Twilio.
const TWILIO_WHATSAPP_FROM = '';

// How long the owner has to approve a broadcast before it is dropped. An unapproved list is
// never sent late: prices from the morning are wrong by the evening.
const APPROVAL_WAIT_HOURS = 4;

// The hard ceiling on one broadcast, enforced in code.
const BROADCAST_CAP = 200;

// ---------------------------------------------------------------- Enquiries (workflow 02)
// A request for this many pieces or more goes to a human for a price.
const HANDOFF_QTY = 10;
// Words that mean a person should answer, whatever else the message says.
const HANDOFF_WORDS = ['order', 'bulk', 'discount', 'best price', 'payment', 'invoice',
  'credit', 'custom', 'repair', 'return', 'complaint', 'urgent'];
const OPT_OUT_WORDS = ['stop', 'unsubscribe', 'remove me'];

// ---------------------------------------------------------------- AI (optional)
// An OpenAI-compatible chat endpoint reads what the customer wants: style, karat, length and
// quantity. It never states a price or stock level; those always come from the sheet, in code.
// Blank key -> keyword rules read the message instead, and the workflow behaves the same.
const AI_API_KEY  = '';
const AI_BASE_URL = 'https://api.openai.com/v1';
const AI_MODEL    = 'gpt-4o-mini';

// ---------------------------------------------------------------- Safety switch
//   TEST_RUN true,  TEST_WHATSAPP blank (how it ships) -> preview. Nothing is sent, nothing is
//                                                         written; every message is shown.
//   TEST_RUN true,  TEST_WHATSAPP set                  -> test. Messages really send, but ALL
//                                                         of them to TEST_WHATSAPP, at most 3
//                                                         per broadcast, marked [TEST]. The
//                                                         sheet is still not written.
//   TEST_RUN false                                     -> live.
// Filling in TEST_WHATSAPP can only ever redirect a message, never cause one.
const TEST_RUN      = true;
const TEST_WHATSAPP = '';

const MODE = TEST_RUN !== true ? 'live' : (TEST_WHATSAPP.trim() !== '' ? 'test' : 'preview');

// ---------------------------------------------------------------- Demo data
// Every row, number and person here is invented. The DEMO rate is not a market price.
// The mix is deliberate: it has to show every decision the engine makes.
//   * priced last time, still in stock         -> repriced at today's rate
//   * qty 0, had stock last time               -> sold out
//   * had 0 last time, stock now               -> back in stock
//   * qty at or under LOW_STOCK_AT             -> last few
//   * never priced before                      -> new in
//   * no weight / a karat not in PURITY        -> held back, with the reason
const DEMO_GOLD_RATE      = 110.00;   // 24k per gram, CURRENCY. DEMO, not a market price.
const DEMO_STOCK = [
  { sku: 'R22-20',  style: 'rope',   purity_k: 22, length_in: 20, weight_g: 18.4, qty: 6,  price: 1930, rate: 108.4, priced_qty: 6,  priced_at: '2026-09-18' },
  { sku: 'R22-24',  style: 'rope',   purity_k: 22, length_in: 24, weight_g: 22.1, qty: 3,  price: 2318, rate: 108.4, priced_qty: 4,  priced_at: '2026-09-18' },
  { sku: 'C22-22',  style: 'cuban',  purity_k: 22, length_in: 22, weight_g: 35.0, qty: 2,  price: 3710, rate: 108.4, priced_qty: 2,  priced_at: '2026-09-18' },
  { sku: 'C18-20',  style: 'cuban',  purity_k: 18, length_in: 20, weight_g: 28.6, qty: 0,  price: 2466, rate: 108.4, priced_qty: 3,  priced_at: '2026-09-18' },
  { sku: 'F18-18',  style: 'figaro', purity_k: 18, length_in: 18, weight_g: 9.8,  qty: 12, price: 842,  rate: 108.4, priced_qty: 12, priced_at: '2026-09-18' },
  { sku: 'F22-20',  style: 'figaro', purity_k: 22, length_in: 20, weight_g: 12.4, qty: 5,  price: 1296, rate: 108.4, priced_qty: 0,  priced_at: '2026-09-18' },
  { sku: 'B21-18',  style: 'box',    purity_k: 21, length_in: 18, weight_g: 14.2, qty: 1,  price: 1388, rate: 108.4, priced_qty: 5,  priced_at: '2026-09-18' },
  { sku: 'FR22-22', style: 'franco', purity_k: 22, length_in: 22, weight_g: 24.0, qty: 4,  price: '',   rate: '',    priced_qty: '', priced_at: '' },
  { sku: 'BL18-16', style: 'ball',   purity_k: 18, length_in: 16, weight_g: 6.5,  qty: 20, price: '',   rate: '',    priced_qty: '', priced_at: '' },
  { sku: 'R22-18',  style: 'rope',   purity_k: 22, length_in: 18, weight_g: '',   qty: 2,  price: '',   rate: '',    priced_qty: '', priced_at: '' },
  { sku: 'C20-20',  style: 'cuban',  purity_k: 20, length_in: 20, weight_g: 30.2, qty: 1,  price: '',   rate: '',    priced_qty: '', priced_at: '' }
];
const DEMO_CUSTOMERS = [
  { name: 'Northgate Jewellers', whatsapp: '+1234567890', opted_out: '' },
  { name: 'Al Noor Gold',        whatsapp: '+1234567890', opted_out: '' },
  { name: 'Riverside Pawn',      whatsapp: '+1234567890', opted_out: 'yes' },
  { name: 'Sunrise Traders',     whatsapp: '0100',         opted_out: '' },
  { name: 'Crown & Chain',       whatsapp: '+1234567890', opted_out: '' }
];
// What workflow 02 answers when run by hand. The same shape Twilio posts to the webhook.
const DEMO_MESSAGES = [
  { From: 'whatsapp:+1234567890', ProfileName: 'Northgate Jewellers', Body: 'Hi, do you have 22k rope chain 20 inch? price?' },
  { From: 'whatsapp:+1234567890', ProfileName: 'Al Noor Gold',        Body: 'figaro 18k' },
  { From: 'whatsapp:+1234567890', ProfileName: 'Crown & Chain',       Body: 'need 40 pcs cuban 22k for my shop, best price?' },
  { From: 'whatsapp:+1234567890', ProfileName: 'Northgate Jewellers', Body: 'can you do a custom 30 inch rope?' },
  { From: 'whatsapp:+1234567890', ProfileName: 'Sunrise Traders',     Body: 'STOP' }
];

const SETTINGS = {
  business_name:   BUSINESS_NAME.trim(),
  owner_name:      OWNER_NAME.trim() || 'the owner',
  owner_whatsapp:  OWNER_WHATSAPP.trim(),
  currency:        CURRENCY.trim().toUpperCase(),
  currency_symbol: CURRENCY_SYMBOL,

  purity:               PURITY,
  styles:               STYLES,
  wholesale_margin_pct: Number(WHOLESALE_MARGIN_PCT) || 0,
  round_to:             Number(ROUND_TO) || 1,

  gold_api_key:      GOLD_API_KEY.trim(),
  gold_api_base:     GOLD_API_BASE.trim().replace(/\/+$/, ''),
  max_rate_move_pct: Number(MAX_RATE_MOVE_PCT) || 3,

  sheet_id:      SHEET_ID.trim(),
  stock_tab:     STOCK_TAB.trim(),
  customers_tab: CUSTOMERS_TAB.trim(),
  low_stock_at:  Number(LOW_STOCK_AT) || 0,

  twilio_whatsapp_from: TWILIO_WHATSAPP_FROM.trim(),
  approval_wait_hours:  Number(APPROVAL_WAIT_HOURS) || 4,
  broadcast_cap:        Number(BROADCAST_CAP) || 0,

  handoff_qty:   Number(HANDOFF_QTY) || 10,
  handoff_words: HANDOFF_WORDS,
  opt_out_words: OPT_OUT_WORDS,

  ai_api_key:  AI_API_KEY.trim(),
  ai_base_url: AI_BASE_URL.trim().replace(/\/+$/, ''),
  ai_model:    AI_MODEL.trim(),

  test_whatsapp: TEST_WHATSAPP.trim(),
  test_cap:      3,
  mode:          MODE,

  demo_gold_rate: DEMO_GOLD_RATE,
  demo_stock:     DEMO_STOCK,
  demo_customers: DEMO_CUSTOMERS,
  demo_messages:  DEMO_MESSAGES,

  // derived flags — the gates read these, never the raw constants
  gold_api_enabled: GOLD_API_KEY.trim() !== '',
  sheet_enabled:    SHEET_ID.trim() !== '',
  ai_enabled:       AI_API_KEY.trim() !== '',
  // Sending needs a sender AND a mode that allows it. In test mode the owner number is not
  // required, because every message is redirected to TEST_WHATSAPP anyway.
  send_enabled: TWILIO_WHATSAPP_FROM.trim() !== '' && MODE !== 'preview'
    && (MODE === 'test' || OWNER_WHATSAPP.trim() !== ''),
  // The sheet is only ever written live. A test run sends real messages and touches nothing.
  write_enabled: SHEET_ID.trim() !== '' && MODE === 'live'
};

// config passes the incoming payload through untouched under `incoming`, so whichever
// trigger fired, the next node reads the payload from the same place. It runs once per item.
const incoming = $input.all().length ? $input.all().map((i) => i.json || {}) : [{}];
return incoming.map((payload) => ({ json: Object.assign({}, SETTINGS, { incoming: payload }) }));

// The sheet hands back one item per row. Collected into one item here so the rest of the run
// reads the stock the same way it reads the demo stock.
const rows = $input.all().map((i) => i.json || {}).filter((r) => String(r.sku || '').trim() !== '');
return [{ json: { source: 'stock sheet', rows } }];

// No stock sheet configured, so the built-in demo stock stands in. Same shape the sheet
// read produces, so everything downstream is identical whichever branch ran.
const cfg = $('config').first().json;
return [{ json: { source: 'demo stock (invented)', rows: cfg.demo_stock } }];

// Reads each WhatsApp message into one shape and makes the keyword read of it. The keyword
// read always runs: with no AI key it IS the read, and with a key it is the fallback when the
// model's answer does not parse.
//
// Messages come from `config` (one item per webhook call). Run by hand, config carries no
// message, so the invented DEMO_MESSAGES stand in. The stock arrives on $input from whichever
// stock branch ran, and rides along on every item so the reply can be built from it.
// Twilio posts form fields (From, Body, ProfileName), sometimes wrapped under `body`.
const cfg = $('config').first().json;
const stock = ($input.first().json || {}).rows || [];
const stockSource = ($input.first().json || {}).source || '';

function unwrap(inc) { return inc && inc.body && typeof inc.body === 'object' ? inc.body : (inc || {}); }
let messages = $('config').all().map((i) => unwrap(i.json.incoming)).filter((m) => m.Body || m.body || m.text);
const demo = messages.length === 0;
if (demo) messages = cfg.demo_messages;

function words(text) { return ' ' + text.toLowerCase().replace(/[^a-z0-9.\s]/g, ' ').replace(/\s+/g, ' ') + ' '; }
const has = (t, w) => t.indexOf(' ' + w + ' ') !== -1;

return messages.map((p) => {
  const text = String(p.Body || p.body || p.text || '').trim();
  const from = String(p.From || p.from || '').replace(/^whatsapp:/, '').trim();
  const name = String(p.ProfileName || p.name || '').trim();
  const t = words(text);

  let style = '';
  for (const key of Object.keys(cfg.styles)) {
    if (cfg.styles[key].words.some((w) => has(t, w))) { style = key; break; }
  }
  const k = t.match(/\s(\d{2})\s?(k|kt|karat|carat|ct)\s/);
  const len = t.match(/\s(\d{2})\s?(in|inch|inches)\s/);
  const qty = t.match(/\s(\d{1,4})\s?(pcs|pc|pieces|piece|units|chains)\s/);

  return { json: {
    from, name, text, demo,
    opt_out: cfg.opt_out_words.some((w) => t.trim() === w || has(t, w)),
    handoff_word: cfg.handoff_words.find((w) => has(t, w)) || '',
    want: {
      style,
      purity_k: k ? Number(k[1]) : null,
      length_in: len ? Number(len[1]) : null,
      qty: qty ? Number(qty[1]) : null
    },
    read_by: 'keyword rules',
    _stock: stock, _stock_source: stockSource
  } };
});

// The model is asked ONE thing: what does this customer want? It returns style, karat, length,
// quantity and whether a person should answer. It is never shown a price or a stock level and
// is never asked to write the reply, so it cannot quote a wrong price or promise stock.
const cfg = $('config').first().json;
return $input.all().map((i) => {
  const styles = Object.keys(cfg.styles).join(', ');
  const body = {
    model: cfg.ai_model,
    temperature: 0,
    response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content:
        'You read WhatsApp messages sent to a gold chain wholesaler. Return JSON only: ' +
        '{"style": one of [' + styles + '] or "", "purity_k": number or null, ' +
        '"length_in": number or null, "qty": number or null, ' +
        '"needs_person": true if they want to order, negotiate, discuss payment, a custom piece, ' +
        'a repair or a complaint, else false, "reason": a few words}. ' +
        'Never invent a value the message does not state.' },
      { role: 'user', content: i.json.text }
    ]
  };
  return { json: Object.assign({}, i.json, { _ai_body: body }) };
});

// Merges the model's reading over the keyword read, field by field. A field the model left
// empty keeps the keyword value; an answer that does not parse keeps the keyword read whole.
// A style the model returns that is not in STYLES is ignored rather than trusted.
const cfg = $('config').first().json;
const asked = $('build the AI request').all();
return $input.all().map((resp, idx) => {
  const base = (asked[idx] || asked[0]).json;
  const out = Object.assign({}, base);
  delete out._ai_body;
  let ai = null;
  try { ai = JSON.parse(resp.json.choices[0].message.content); } catch (e) { ai = null; }
  if (!ai || typeof ai !== 'object') return { json: Object.assign(out, { read_by: 'keyword rules (AI answer did not parse)' }) };
  const want = Object.assign({}, base.want);
  if (ai.style && cfg.styles[ai.style]) want.style = ai.style;
  for (const f of ['purity_k', 'length_in', 'qty']) if (Number(ai[f]) > 0) want[f] = Number(ai[f]);
  return { json: Object.assign(out, {
    want,
    handoff_word: base.handoff_word || (ai.needs_person === true ? 'AI: ' + (ai.reason || 'needs a person') : ''),
    read_by: 'AI (' + cfg.ai_model + ')'
  }) };
});

// Reached two ways: no AI key, or the AI request failed. Either way the keyword read from
// `read the message` stands, unchanged. The reply is built the same way both times, because
// the AI only ever reads; it never answers.
const cfg = $('config').first().json;
const why = cfg.ai_enabled ? 'keyword rules (AI request failed)' : 'keyword rules (no AI key)';
return $('read the message').all().map((i) => ({ json: Object.assign({}, i.json, { read_by: why }) }));

// Builds the reply to every message, and the alert to the owner where a person should step in.
// The rule that makes this safe to leave running: EVERY price and stock figure in a reply is
// read from the stock sheet, from the price workflow 01 last published. The AI never writes
// a reply and never states a number. In order, a message is:
//   opted out    -> confirmed, and marked so no list is ever sent to them again
//   a handoff    -> an order, a bulk quantity, a custom piece, a complaint: acknowledged, and
//                   the owner is told who, what and why. The bot does not negotiate.
//   a question   -> answered from stock: exact match, or the nearest in-stock alternatives
//   unreadable   -> asked which style and karat, with the styles actually in stock
// One item out per message to send: kind 'reply' (to the customer) or 'owner' (the alert).
const cfg = $('config').first().json;
// ---- shared pricing (build/js/lib-pricing.js, inlined by build.js) ----
// One definition of "what a chain costs today", used by the repricing run and by every
// WhatsApp answer, so a price quoted in chat can never disagree with the price list.

function num(v) {
  if (v === null || v === undefined) return NaN;
  const s = String(v).replace(/[^0-9.\-]/g, '');
  return s === '' ? NaN : Number(s);
}

// A row the way a sheet or the demo hands it over, into one typed shape. Nothing is guessed:
// a value that does not parse stays NaN and the check step says so.
function readRow(r) {
  return {
    sku:        String(r.sku || '').trim(),
    style:      String(r.style || '').trim().toLowerCase(),
    purity_k:   num(r.purity_k),
    length_in:  num(r.length_in),
    weight_g:   num(r.weight_g),
    qty:        num(r.qty),
    prev_price: num(r.price),
    prev_rate:  num(r.rate),
    prev_qty:   num(r.priced_qty),
    priced_at:  String(r.priced_at || '').trim()
  };
}

function priceChain(row, rate24, cfg) {
  const purity = cfg.purity[row.purity_k];
  const style = cfg.styles[row.style];
  const metal = row.weight_g * purity * rate24;
  const making = row.weight_g * style.making_per_gram;
  const gross = (metal + making) * (1 + cfg.wholesale_margin_pct / 100);
  const step = cfg.round_to || 1;
  return {
    metal_value: Math.round(metal * 100) / 100,
    making_value: Math.round(making * 100) / 100,
    price: Math.round(gross / step) * step
  };
}

function money(v, cfg) {
  return cfg.currency_symbol + Number(v).toLocaleString('en-US', { maximumFractionDigits: 2 });
}

function chainLabel(row, cfg) {
  const style = cfg.styles[row.style];
  return row.purity_k + 'k ' + (style ? style.label : row.style) + ' ' + row.length_in + 'in';
}
// ---- end shared pricing ----
const out = [];
for (const item of $input.all()) {
  const m = item.json;
  const w = m.want || {};
  const rows = (m._stock || []).map(readRow).filter((r) => cfg.styles[r.style] && cfg.purity[r.purity_k]);
  const who = m.name || m.from;
  const reply = (body, extra) => out.push({ json: Object.assign({ kind: 'reply', to: m.from, customer: who,
    message: m.text, read_by: m.read_by, body }, extra || {}) });
  const owner = (why) => out.push({ json: { kind: 'owner', to: cfg.owner_whatsapp, customer: who,
    message: m.text, body: 'Needs you: ' + who + ' (' + m.from + ')\nWhy: ' + why + '\nThey said: "' + m.text + '"' } });

  if (m.opt_out) {
    reply("Done. You won't receive our price lists any more. Message us any time if you need anything.",
      { opt_out_record: { whatsapp: m.from, opted_out: 'yes' } });
    continue;
  }

  const bigOrder = w.qty && w.qty >= cfg.handoff_qty;
  if (m.handoff_word || bigOrder) {
    const why = bigOrder ? w.qty + ' pieces (HANDOFF_QTY is ' + cfg.handoff_qty + ')' : 'asked about "' + m.handoff_word + '"';
    reply('Thanks, ' + (m.name || 'there') + '. ' + cfg.owner_name.charAt(0).toUpperCase() + cfg.owner_name.slice(1) +
      ' will reply to you personally about this shortly.', { handoff: why });
    owner(why);
    continue;
  }

  if (!w.style && !w.purity_k) {
    const styles = Object.keys(cfg.styles).filter((s) => rows.some((r) => r.style === s && r.qty > 0))
      .map((s) => cfg.styles[s].label);
    reply('Happy to help. Which chain are you after? In stock today: ' + styles.join(', ') +
      '. Tell me the style and karat (e.g. "22k rope 20 inch").');
    continue;
  }

  const fits = (r) => (!w.style || r.style === w.style) && (!w.purity_k || r.purity_k === w.purity_k);
  const inStock = rows.filter((r) => fits(r) && r.qty > 0)
    .sort((a, b) => Math.abs((a.length_in || 0) - (w.length_in || a.length_in)) - Math.abs((b.length_in || 0) - (w.length_in || b.length_in)));
  const exact = w.length_in ? inStock.filter((r) => r.length_in === w.length_in) : inStock;
  const show = (exact.length ? exact : inStock).slice(0, 3);
  const asked = [w.purity_k ? w.purity_k + 'k' : '', w.style ? cfg.styles[w.style].label : '', w.length_in ? w.length_in + 'in' : '']
    .filter(Boolean).join(' ');

  const priceOf = (r) => (r.prev_price > 0 ? money(r.prev_price, cfg) : 'price on request');
  const lines = show.map((r) => '• ' + chainLabel(r, cfg) + ' · ' + r.weight_g + ' g · ' + priceOf(r) + ' · ' +
    (r.qty <= cfg.low_stock_at ? 'last ' + r.qty : r.qty + ' pcs'));
  const listedOn = show.map((r) => r.priced_at).filter(Boolean).sort().pop();

  if (!show.length) {
    reply('Sorry, no ' + asked + ' in stock right now. I have let ' + cfg.owner_name + ' know you asked.');
    owner('asked for ' + asked + ', none in stock');
    continue;
  }
  const lead = exact.length || !w.length_in ? 'Yes, ' + asked + ' in stock:' : 'No ' + asked + ' right now. Closest in stock:';
  reply([lead].concat(lines,
    listedOn ? ['Prices from our list of ' + listedOn + '. Reply "order" and the number of pieces to reserve.'] :
               ['Reply "order" and the number of pieces to reserve.']).join('\n'));
}
return out;

// The one place that decides where a message actually goes. Live: to the customer, and alerts
// to OWNER_WHATSAPP. Test: everything to TEST_WHATSAPP, at most test_cap, marked [TEST] with
// the real recipient. An owner alert with no OWNER_WHATSAPP is not sent and says so.
const cfg = $('config').first().json;
const out = [];
for (const i of $input.all()) {
  const m = i.json;
  if (m.kind === 'owner' && !cfg.owner_whatsapp && cfg.mode === 'live') continue;
  if (cfg.mode === 'test') {
    if (out.length >= cfg.test_cap) break;
    out.push({ json: Object.assign({}, m, { to: cfg.test_whatsapp,
      body: '[TEST: would go to ' + (m.kind === 'owner' ? 'the owner' : m.customer + ' ' + m.to) + ']\n' + m.body }) });
  } else out.push({ json: m });
}
return out.map((o) => ({ json: Object.assign({}, o.json, { to: String(o.json.to || '').replace(/^whatsapp:/, '') }) }));

// Sending is off (TEST_RUN is true with TEST_WHATSAPP blank, or no Twilio sender). Nothing
// was sent. This node IS the result: each message, how it was read, and the exact reply and
// owner alert it would have produced.
const cfg = $('config').first().json;
return $input.all().map((i) => ({ json: {
  _outcome: 'preview: not sent',
  _reason: cfg.twilio_whatsapp_from ? 'mode is ' + cfg.mode : 'no TWILIO_WHATSAPP_FROM, preview only',
  kind: i.json.kind,
  to: i.json.kind === 'owner' ? 'the owner' : i.json.customer + ' ' + i.json.to,
  they_said: i.json.message,
  read_by: i.json.read_by || '',
  would_send: i.json.body
} }));

// An opt-out is written to the Customers tab, matched on the number, so workflow 01 never
// messages them again. Nothing else on the row is touched.
return $('decide the reply').all()
  .filter((i) => i.json.opt_out_record)
  .map((i) => ({ json: i.json.opt_out_record }));

// The sheet is only written live. These opt-outs were NOT recorded; in live mode they would be.
const cfg = $('config').first().json;
return [{ json: {
  _outcome: 'preview: opt-outs not recorded',
  _reason: cfg.sheet_enabled ? 'mode is ' + cfg.mode + '; the sheet is only written live' : 'no SHEET_ID',
  would_write: $input.all().map((i) => i.json)
} }];
